var appendToStream = (pool, streamName, streamType, messages, options) => pool.withTransaction(async (transaction) => {
  const { execute } = transaction;
  if (messages.length === 0)
    return { success: false, result: { success: false } };
  try {
    const expectedStreamVersion = toExpectedVersion(
      options?.expectedStreamVersion
    );
    const messagesToAppend = messages.map((e) => ({
      ...e,
      kind: e.kind ?? "Event",
      metadata: {
        messageId: uuid5(),
        ..."metadata" in e ? e.metadata ?? {} : {}
      }
    }));
    const {
      success,
      next_stream_position,
      global_positions,
      transaction_id
    } = await appendEventsRaw(
      execute,
      streamName,
      streamType,
      messagesToAppend,
      {
        expectedStreamVersion
      }
    );
    if (!success || next_stream_position === null || global_positions === null || global_positions.length === 0 || transaction_id == null) {
      return {
        success: false,
        result: { success: false }
      };
    }
    const nextStreamPosition = BigInt(next_stream_position);
    const globalPositions = global_positions.map(BigInt);
    globalPositions.forEach((globalPosition, index) => {
      messagesToAppend[index].metadata = {
        ...messagesToAppend[index].metadata,
        streamName,
        streamPosition: nextStreamPosition - BigInt(messagesToAppend.length) + BigInt(index + 1),
        globalPosition
      };
    });
    if (options?.beforeCommitHook)
      await options.beforeCommitHook(messagesToAppend, { transaction });
    return {
      success: true,
      result: {
        success: true,
        nextStreamPosition,
        globalPositions,
        transactionId: transaction_id
      }
    };
  } catch (error) {
    if (!isOptimisticConcurrencyError(error)) throw error;
    return {
      success: false,
      result: { success: false }
    };
  }
});
var toExpectedVersion = (expected) => {
  if (expected === void 0) return null;
  if (expected === NO_CONCURRENCY_CHECK) return null;
  if (expected == STREAM_DOES_NOT_EXIST) return null;
  if (expected == STREAM_EXISTS) return null;
  return expected;
};
var isOptimisticConcurrencyError = (error) => error instanceof Error && "code" in error && error.code === "23505";
var appendEventsRaw = (execute, streamId, streamType, messages, options) => single4(
  execute.command(
    callAppendToStream({
      messageIds: messages.map((e) => sql7("%L", e.metadata.messageId)).join(","),
      messagesData: messages.map((e) => sql7("%L", JSONParser.stringify(e.data))).join(","),
      messagesMetadata: messages.map((e) => {
        const { messageId: _messageId, ...rawMetadata } = e.metadata;
        return sql7("%L", JSONParser.stringify(rawMetadata));
      }).join(","),
      schemaVersions: messages.map(() => `'1'`).join(","),
      messageTypes: messages.map((e) => sql7("%L", e.type)).join(","),
      messageKinds: messages.map((e) => sql7("%L", e.kind === "Event" ? "E" : "C")).join(","),
      streamId,
      streamType,
      expectedStreamPosition: options?.expectedStreamVersion?.toString() ?? "NULL",
      partition: options?.partition ?? defaultTag
    })
  )
);

